/**
 * Elliot embeddable chat widget.
 *
 * Usage (on a client's own website):
 *   <script src="https://elliot-real-estate-five.vercel.app/widget.js" data-tenant="acme-realty" async></script>
 *
 * Optional data attributes on the same <script> tag:
 *   data-webhook-url  -- override the chat webhook endpoint (defaults to production)
 *   data-title        -- header text, default "Chat with us"
 *   data-greeting     -- first bubble shown before the visitor sends anything.
 *                        This is static UI text, NOT generated by Elliot -- the
 *                        chat webhook requires a real message to respond to
 *                        (see Validate Input in 01-main-ai-agent.json), so there
 *                        is no way to get a real AI-authored opening line before
 *                        the visitor has said something.
 *   data-accent       -- accent color (hex), default "#111111"
 *
 * Deliberately vanilla JS, no build step, no framework runtime shipped to the
 * host page -- this file is the whole widget. It renders into a Shadow DOM so
 * its styles can never leak into (or be broken by) the host site's CSS.
 *
 * Talks directly to the "chat" webhook (01-main-ai-agent.json). Request/response
 * contract, confirmed against that workflow's Validate Input / Respond to
 * Webhook nodes:
 *   POST { tenant_slug, message, conversation_id?, contact?: {name,email,phone} }
 *   ->   { conversation_id, reply }
 *
 * KNOWN GAP, not fixable from this file: that webhook has no auth (same as
 * every other n8n webhook in this project so far -- see KNOWN_ISSUES.md).
 * Anyone who finds the URL and a tenant_slug can call it directly. Fine for a
 * pilot; needs revisiting before this is handed to many clients at once.
 */
(function () {
  "use strict";

  var DEFAULT_WEBHOOK_URL = "https://makodevops.app.n8n.cloud/webhook/chat";

  var scriptEl = document.currentScript;
  if (!scriptEl) {
    console.error("[elliot-widget] could not find its own <script> tag (document.currentScript is null) -- widget not mounted");
    return;
  }

  var TENANT = scriptEl.dataset.tenant;
  if (!TENANT) {
    console.error("[elliot-widget] missing required data-tenant attribute -- widget not mounted");
    return;
  }

  var WEBHOOK_URL = scriptEl.dataset.webhookUrl || DEFAULT_WEBHOOK_URL;
  var TITLE = scriptEl.dataset.title || "Chat with us";
  var GREETING = scriptEl.dataset.greeting || "Hi! How can I help you today?";
  var ACCENT = scriptEl.dataset.accent || "#111111";
  var STORAGE_KEY = "elliot_conversation_id:" + TENANT;

  // sessionStorage, not localStorage: a conversation survives page navigation
  // within the same tab/session (so multi-page chats stay coherent) but resets
  // on a new tab or browser restart. Deliberate, documented tradeoff -- swap
  // to localStorage here if longer persistence across visits is wanted later.
  function getConversationId() {
    try {
      return sessionStorage.getItem(STORAGE_KEY);
    } catch (e) {
      return null; // storage can throw in some privacy modes; degrade to no persistence
    }
  }
  function setConversationId(id) {
    try {
      sessionStorage.setItem(STORAGE_KEY, id);
    } catch (e) {
      /* ignore */
    }
  }

  function escapeHtml(str) {
    var div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }

  // ---- Build the DOM, isolated in a Shadow Root ----

  var host = document.createElement("div");
  host.id = "elliot-widget-host";
  document.body.appendChild(host);
  var root = host.attachShadow({ mode: "open" });

  var style = document.createElement("style");
  style.textContent =
    ":host{all:initial}" +
    "*{box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}" +
    ".bubble{position:fixed;bottom:20px;right:20px;width:56px;height:56px;border-radius:50%;background:" + ACCENT + ";color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.25);z-index:2147483000;border:none}" +
    ".bubble svg{width:26px;height:26px}" +
    ".panel{position:fixed;bottom:88px;right:20px;width:340px;max-width:calc(100vw - 40px);height:480px;max-height:calc(100vh - 120px);background:#fff;border-radius:14px;box-shadow:0 8px 30px rgba(0,0,0,.25);display:none;flex-direction:column;overflow:hidden;z-index:2147483000}" +
    ".panel.open{display:flex}" +
    ".header{background:" + ACCENT + ";color:#fff;padding:14px 16px;font-size:14px;font-weight:600;display:flex;justify-content:space-between;align-items:center}" +
    ".header button{background:none;border:none;color:#fff;font-size:18px;cursor:pointer;line-height:1;padding:2px 6px}" +
    ".messages{flex:1;overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px;background:#f7f7f8}" +
    ".msg{max-width:80%;padding:8px 12px;border-radius:10px;font-size:13px;line-height:1.4;white-space:pre-wrap;word-wrap:break-word}" +
    ".msg.user{align-self:flex-end;background:" + ACCENT + ";color:#fff;border-bottom-right-radius:3px}" +
    ".msg.assistant{align-self:flex-start;background:#fff;color:#111;border:1px solid #e5e5e5;border-bottom-left-radius:3px}" +
    ".msg.error{align-self:flex-start;background:#fdecea;color:#7c2d20;border:1px solid #f3c6c0}" +
    ".typing{align-self:flex-start;display:flex;gap:3px;padding:10px 12px}" +
    ".typing span{width:6px;height:6px;border-radius:50%;background:#999;display:inline-block;animation:elliot-bounce 1.2s infinite}" +
    ".typing span:nth-child(2){animation-delay:.2s}.typing span:nth-child(3){animation-delay:.4s}" +
    "@keyframes elliot-bounce{0%,60%,100%{transform:translateY(0);opacity:.4}30%{transform:translateY(-4px);opacity:1}}" +
    ".inputRow{display:flex;border-top:1px solid #e5e5e5;padding:8px}" +
    ".inputRow textarea{flex:1;resize:none;border:none;outline:none;font-size:13px;padding:8px;max-height:80px;font-family:inherit}" +
    ".inputRow button{background:" + ACCENT + ";color:#fff;border:none;border-radius:8px;padding:0 14px;cursor:pointer;font-size:13px;margin-left:6px}" +
    ".inputRow button:disabled{opacity:.5;cursor:default}";
  root.appendChild(style);

  var bubble = document.createElement("button");
  bubble.className = "bubble";
  bubble.setAttribute("aria-label", "Open chat");
  bubble.innerHTML =
    '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4 4h16v12H7l-3 3V4z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg>';
  root.appendChild(bubble);

  var panel = document.createElement("div");
  panel.className = "panel";
  panel.innerHTML =
    '<div class="header"><span></span><button aria-label="Close chat">\u00d7</button></div>' +
    '<div class="messages"></div>' +
    '<div class="inputRow">' +
    '<textarea rows="1" placeholder="Type a message..."></textarea>' +
    "<button>Send</button>" +
    "</div>";
  root.appendChild(panel);

  panel.querySelector(".header span").textContent = TITLE;
  var messagesEl = panel.querySelector(".messages");
  var textareaEl = panel.querySelector("textarea");
  var sendBtn = panel.querySelector(".inputRow button");
  var closeBtn = panel.querySelector(".header button");

  var conversationId = getConversationId();
  var isOpen = false;
  var isSending = false;
  var hasGreeted = false;

  function addMessage(role, text) {
    var div = document.createElement("div");
    div.className = "msg " + role;
    div.innerHTML = escapeHtml(text).replace(/\n/g, "<br>");
    messagesEl.appendChild(div);
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  function showTyping() {
    var div = document.createElement("div");
    div.className = "typing";
    div.id = "elliot-typing";
    div.innerHTML = "<span></span><span></span><span></span>";
    messagesEl.appendChild(div);
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }
  function hideTyping() {
    var el = messagesEl.querySelector("#elliot-typing");
    if (el) el.remove();
  }

  function setSending(state) {
    isSending = state;
    sendBtn.disabled = state;
    textareaEl.disabled = state;
  }

  function openPanel() {
    isOpen = true;
    panel.classList.add("open");
    if (!hasGreeted) {
      addMessage("assistant", GREETING);
      hasGreeted = true;
    }
    textareaEl.focus();
  }
  function closePanel() {
    isOpen = false;
    panel.classList.remove("open");
  }

  bubble.addEventListener("click", function () {
    if (isOpen) {
      closePanel();
    } else {
      openPanel();
    }
  });
  closeBtn.addEventListener("click", closePanel);

  function send() {
    var text = textareaEl.value.trim();
    if (!text || isSending) return;

    addMessage("user", text);
    textareaEl.value = "";
    setSending(true);
    showTyping();

    var payload = { tenant_slug: TENANT, message: text };
    if (conversationId) payload.conversation_id = conversationId;

    fetch(WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then(function (res) {
        if (!res.ok) {
          throw new Error("chat webhook returned " + res.status);
        }
        return res.json();
      })
      .then(function (data) {
        hideTyping();
        setSending(false);
        if (data.conversation_id) {
          conversationId = data.conversation_id;
          setConversationId(conversationId);
        }
        if (data.reply) {
          addMessage("assistant", data.reply);
        } else {
          addMessage("error", "Sorry, something went wrong. Please try again.");
        }
      })
      .catch(function (err) {
        hideTyping();
        setSending(false);
        addMessage("error", "Sorry, something went wrong. Please try again.");
        console.error("[elliot-widget] send failed:", err);
      });
  }

  sendBtn.addEventListener("click", send);
  textareaEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  });
  textareaEl.addEventListener("input", function () {
    textareaEl.style.height = "auto";
    textareaEl.style.height = Math.min(textareaEl.scrollHeight, 80) + "px";
  });
})();
